// Fake `copilot` (GitHub Copilot CLI) for Windows CI, started through copilot.cmd, an npm shim like the real one.
//
// It checks the arguments CopilotProvider passes (-p <task> --no-color --stream on --disallow-temp-dir, a --log-dir
// that exists, tool permissions) and prints plain text lines ending in CR LF, with ANSI colour codes the provider
// must strip. It echoes the task as `TASK<...>` so tests can see it arrived unchanged (spaces, quotes, &, %).
// A task containing "sleep" leaves a sleeping process tree; "fail" writes an error to stderr and exits 1.
'use strict';
const fs = require('fs');
const path = require('path');
const { EOL, record, option, sleepTree } = require('fake-common');

const argv = process.argv.slice(2);
record('copilot', argv);
const task = option(argv, '-p');
const logDir = option(argv, '--log-dir');
if (task === undefined || !argv.includes('--no-color') || option(argv, '--stream') !== 'on') {
  process.stderr.write('fake copilot: expected -p <task> --no-color --stream on' + EOL);
  process.exit(64);
}
if (logDir !== undefined) {
  // The provider creates this folder (no POSIX modes on Windows); the CLI writes its logs there.
  fs.writeFileSync(path.join(logDir, 'session.log'), 'fake copilot log' + EOL);
}
const tools = argv.includes('--allow-all-tools') ? 'all' : 'limited';

if (/\bsleep\b/.test(task)) {
  process.stdout.write('sleeping' + EOL);
  sleepTree();
} else if (/\bfail\b/.test(task)) {
  process.stderr.write('\u001b[31mError:\u001b[0m fake copilot is not logged in' + EOL);
  process.exit(1);
} else {
  process.stdout.write('\u001b[1mWorking on it\u001b[0m' + EOL);
  process.stdout.write(`TASK<${task}>` + EOL);
  process.stdout.write(`tools: ${tools}` + EOL);
  process.stdout.write(EOL);
  process.stdout.write('Final answer: hello from fake copilot' + EOL);
  process.exit(0);
}
